package cn.hospital.rehab.common.audit;
import cn.hospital.rehab.common.api.ApiResponse;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.web.bind.annotation.*;import java.time.OffsetDateTime;import java.util.List;
@RestController @RequestMapping("/api/system/audit-logs") public class AuditLogController {private final JdbcClient jdbc;public AuditLogController(JdbcClient jdbc){this.jdbc=jdbc;}@GetMapping ApiResponse<List<AuditLog>> list(@RequestParam(required=false)String businessType,@RequestParam(required=false)String businessId){String t=businessType==null?"":businessType.trim(),id=businessId==null?"":businessId.trim();return ApiResponse.ok(jdbc.sql("SELECT id,module_code,business_type,business_id,action_type,operator_name,before_data::text before_data,after_data::text after_data,client_ip,operated_at FROM operation_audit_log WHERE (:type='' OR business_type=:type) AND (:id='' OR business_id=:id) ORDER BY operated_at DESC LIMIT 500").param("type",t).param("id",id).query((r,n)->new AuditLog(r.getLong("id"),r.getString("module_code"),r.getString("business_type"),r.getString("business_id"),r.getString("action_type"),r.getString("operator_name"),r.getString("before_data"),r.getString("after_data"),r.getString("client_ip"),r.getObject("operated_at",OffsetDateTime.class))).list());}public record AuditLog(long id,String moduleCode,String businessType,String businessId,String actionType,String operatorName,String beforeData,String afterData,String clientIp,OffsetDateTime operatedAt){}
}
